"""Render the PRD markdown (generated by templates/prd.md.j2) into a bank-style PDF.

Requires: reportlab, pyyaml.
Supported Markdown: front matter, #/##/### headings, paragraphs, "-" bullets,
"1." numbered lists, pipe tables, **bold**, *italic*, `code`, ">" callouts.
"""

import os
import re

from datetime import date

import yaml
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import LETTER
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib.units import inch
from reportlab.lib.utils import ImageReader
from reportlab.pdfbase.pdfmetrics import stringWidth
from reportlab.pdfgen import canvas as rl_canvas
from reportlab.platypus import (
    BaseDocTemplate,
    HRFlowable,
    Frame,
    NextPageTemplate,
    PageBreak,
    PageTemplate,
    Paragraph,
    Spacer,
    Table,
    TableStyle,
)
from reportlab.platypus.tableofcontents import TableOfContents

# ---- House style: Wells Fargo ----------------------------------------------
# Colour values come from third-party brand-colour sites, which disagree with
# each other. Replace them with the official values from the internal brand
# portal before production use.
# Accessibility (WCAG 2.1): white on primary red = 5.1:1 (passes AA).
# White on gold = 1.5:1 (FAILS) — gold is used only for bars, rules, and as a
# background behind dark text, never as text colour on white.
BRAND = {
    "name": "Wells Fargo",
    "primary": colors.HexColor("#D71E28"),  # red: bars, table headers, headings
    "accent": colors.HexColor("#FFCD11"),  # gold: accent bars and rules only
    "rule": colors.HexColor("#E5DED6"),
    "zebra": colors.HexColor("#FAF7F2"),
    "callout": colors.HexColor("#FFF8E1"),
    "text": colors.HexColor("#3B3331"),
    "muted": colors.HexColor("#6B605B"),
}
# Optional: path to an approved logo file (PNG) from the internal brand portal.
# Leave empty to show the bank name as text. Do not recreate the logo by hand.
LOGO_PATH = os.environ.get("ASSAY_LOGO_PATH", "")
LOGO_HEIGHT = 0.32 * inch
PAGE = LETTER
MARGIN = 0.9 * inch
# ---------------------------------------------------------------------------

BASE = "Helvetica"
BOLD = "Helvetica-Bold"


def styles():
    s = {}
    s["body"] = ParagraphStyle(
        "body",
        fontName=BASE,
        fontSize=10,
        leading=14.5,
        textColor=BRAND["text"],
        spaceAfter=6,
        alignment=TA_LEFT,
    )
    s["h1"] = ParagraphStyle(
        "h1",
        fontName=BOLD,
        fontSize=16,
        leading=20,
        textColor=BRAND["primary"],
        spaceBefore=16,
        spaceAfter=8,
    )
    s["h2"] = ParagraphStyle(
        "h2",
        fontName=BOLD,
        fontSize=12.5,
        leading=16,
        textColor=BRAND["primary"],
        spaceBefore=12,
        spaceAfter=5,
    )
    s["h3"] = ParagraphStyle(
        "h3",
        fontName=BOLD,
        fontSize=10.5,
        leading=14,
        textColor=BRAND["text"],
        spaceBefore=8,
        spaceAfter=4,
    )
    s["bullet"] = ParagraphStyle(
        "bullet", parent=s["body"], leftIndent=16, bulletIndent=4, spaceAfter=3
    )
    s["cell"] = ParagraphStyle(
        "cell", fontName=BASE, fontSize=8.5, leading=11, textColor=BRAND["text"]
    )
    s["cellh"] = ParagraphStyle(
        "cellh", fontName=BOLD, fontSize=8.5, leading=11, textColor=colors.white
    )
    s["callout"] = ParagraphStyle(
        "callout",
        parent=s["body"],
        textColor=BRAND["muted"],
        fontName="Helvetica-Oblique",
        spaceAfter=0,
    )
    s["cover_title"] = ParagraphStyle(
        "ct", fontName=BOLD, fontSize=26, leading=31, textColor=BRAND["primary"]
    )
    s["cover_sub"] = ParagraphStyle(
        "cs", fontName=BASE, fontSize=14, leading=18, textColor=BRAND["muted"]
    )
    s["label"] = ParagraphStyle(
        "label", fontName=BOLD, fontSize=8.5, leading=11, textColor=BRAND["muted"]
    )
    s["toc0"] = ParagraphStyle(
        "toc0", fontName=BOLD, fontSize=10, leading=15, textColor=BRAND["text"]
    )
    s["toc1"] = ParagraphStyle(
        "toc1", fontName=BASE, fontSize=9.5, leading=13, leftIndent=16, textColor=BRAND["muted"]
    )
    return s


ST = styles()


def inline(text):
    """Escape XML and convert **bold**, *italic*, `code`."""
    text = text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    text = re.sub(r"\*\*(.+?)\*\*", r"<b>\1</b>", text)
    text = re.sub(r"(?<!\*)\*(?!\s)(.+?)(?<!\s)\*(?!\*)", r"<i>\1</i>", text)
    text = re.sub(r"`(.+?)`", r'<font face="Courier">\1</font>', text)
    return text


def split_front_matter(raw):
    m = re.match(r"^---\s*\n(.*?)\n---\s*\n(.*)$", raw, re.S)
    if not m:
        raise ValueError("PRD markdown must start with YAML front matter between --- lines.")
    meta = yaml.safe_load(m.group(1)) or {}
    for key in ("title", "doc_id", "version", "status", "classification"):
        if not meta.get(key):
            raise ValueError(f"Front matter is missing required field: {key}")
    return meta, m.group(2)


def make_table(rows, avail_width, header=True):
    ncols = max(len(r) for r in rows)
    rows = [r + [""] * (ncols - len(r)) for r in rows]
    # Each column gets at least the width of its longest word, so IDs, dates
    # and headers never break mid-word. Spare width goes to wordy columns.
    pad = 12
    mins = []
    for c in range(ncols):
        words = [w for r in rows for w in re.sub(r"[*`]", "", r[c]).split()] or [""]
        font = BOLD if header else BASE
        mins.append(max(stringWidth(w, font, 8.5) for w in words) + pad)
    lens = [max(min(len(r[c]), 80) for r in rows) + 1 for c in range(ncols)]
    if sum(mins) >= avail_width:
        widths = [avail_width * m / sum(mins) for m in mins]
    else:
        spare = avail_width - sum(mins)
        weights = [max(l - m / 5, 1) for l, m in zip(lens, mins)]
        widths = [m + spare * w / sum(weights) for m, w in zip(mins, weights)]
    data = []
    for i, r in enumerate(rows):
        st = ST["cellh"] if (header and i == 0) else ST["cell"]
        data.append([Paragraph(inline(c), st) for c in r])
    t = Table(data, colWidths=widths, repeatRows=1 if header else 0, hAlign="LEFT")
    cmds = [
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("LINEBELOW", (0, 0), (-1, -1), 0.5, BRAND["rule"]),
        ("TOPPADDING", (0, 0), (-1, -1), 4),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
        ("LEFTPADDING", (0, 0), (-1, -1), 5),
        ("RIGHTPADDING", (0, 0), (-1, -1), 5),
    ]
    if header:
        cmds.append(("BACKGROUND", (0, 0), (-1, 0), BRAND["primary"]))
    start = 1 if header else 0
    for i in range(start, len(data)):
        if (i - start) % 2 == 1:
            cmds.append(("BACKGROUND", (0, i), (-1, i), BRAND["zebra"]))
    t.setStyle(TableStyle(cmds))
    return t


def parse_row(line):
    line = line.strip().strip("|")
    return [c.strip() for c in line.split("|")]


def body_flowables(md, avail_width):
    out = []
    lines = md.splitlines()
    i = 0
    para = []

    def flush():
        if para:
            out.append(Paragraph(inline(" ".join(para)), ST["body"]))
            para.clear()

    while i < len(lines):
        line = lines[i].rstrip()
        stripped = line.strip()
        if not stripped:
            flush()
            i += 1
            continue
        h = re.match(r"^(#{1,3})\s+(.*)$", stripped)
        if h:
            flush()
            level = len(h.group(1))
            p = Paragraph(inline(h.group(2)), ST[f"h{level}"])
            p._toc_level = level - 1 if level <= 2 else None
            out.append(p)
            if level == 1:
                out.append(
                    HRFlowable(
                        width="12%",
                        thickness=2.5,
                        color=BRAND["accent"],
                        hAlign="LEFT",
                        spaceBefore=0,
                        spaceAfter=8,
                    )
                )
            i += 1
            continue
        if stripped.startswith("|"):
            flush()
            block = []
            while i < len(lines) and lines[i].strip().startswith("|"):
                block.append(lines[i])
                i += 1
            rows = [
                parse_row(b)
                for b in block
                if not re.match(r"^\|?\s*:?-{2,}", b.strip().strip("|").strip())
            ]
            if rows:
                out.append(make_table(rows, avail_width))
                out.append(Spacer(1, 8))
            continue
        if stripped.startswith(">"):
            flush()
            quote = []
            while i < len(lines) and lines[i].strip().startswith(">"):
                quote.append(lines[i].strip()[1:].strip())
                i += 1
            box = Table(
                [[Paragraph(inline(" ".join(quote)), ST["callout"])]], colWidths=[avail_width]
            )
            box.setStyle(
                TableStyle(
                    [
                        ("BACKGROUND", (0, 0), (-1, -1), BRAND["callout"]),
                        ("LINEBEFORE", (0, 0), (0, -1), 3, BRAND["accent"]),
                        ("LEFTPADDING", (0, 0), (-1, -1), 10),
                        ("TOPPADDING", (0, 0), (-1, -1), 6),
                        ("BOTTOMPADDING", (0, 0), (-1, -1), 6),
                    ]
                )
            )
            out.append(box)
            out.append(Spacer(1, 8))
            continue
        b = re.match(r"^[-*]\s+(.*)$", stripped)
        n = re.match(r"^(\d+)\.\s+(.*)$", stripped)
        if b or n:
            flush()
            bullet = "\u2022" if b else f"{n.group(1)}."
            text = b.group(1) if b else n.group(2)
            out.append(Paragraph(inline(text), ST["bullet"], bulletText=bullet))
            i += 1
            continue
        para.append(stripped)
        i += 1
    flush()
    return out


def cover_and_control(meta, avail_width):
    out = [Spacer(1, 1.7 * inch)]
    out.append(Paragraph(inline(str(meta["title"])), ST["cover_title"]))
    out.append(Spacer(1, 6))
    out.append(
        Paragraph(
            inline(str(meta.get("subtitle", "Product Requirements Document"))), ST["cover_sub"]
        )
    )
    out.append(Spacer(1, 0.5 * inch))
    rows = [
        ["Document ID", str(meta["doc_id"])],
        ["Version", str(meta["version"])],
        ["Status", str(meta["status"])],
        ["Date", str(meta.get("date", date.today()))],
        ["Owner", str(meta.get("owner", ""))],
        ["Sponsor", str(meta.get("sponsor", ""))],
        ["Classification", str(meta["classification"])],
    ]
    out.append(make_table(rows, avail_width * 0.6, header=False))
    out.append(NextPageTemplate("body"))
    out.append(PageBreak())

    out.append(Paragraph("Document control", ST["h1"]))
    out.append(Paragraph("Version history", ST["h2"]))
    vh = [["Version", "Date", "Author", "Change"]]
    for v in meta.get("version_history") or []:
        vh.append(
            [
                str(v.get("version", "")),
                str(v.get("date", "")),
                str(v.get("author", "")),
                str(v.get("change", "")),
            ]
        )
    out.append(make_table(vh, avail_width))
    out.append(Spacer(1, 12))
    out.append(Paragraph("Approvals", ST["h2"]))
    out.append(
        Paragraph(
            "Approval confirms the requirements are complete and accurate "
            "for the stated scope. It does not confirm regulatory compliance "
            "unless the approver's role is Compliance.",
            ST["body"],
        )
    )
    ap = [["Name", "Role", "Decision", "Signature", "Date"]]
    for a in meta.get("approvers") or []:
        ap.append(
            [
                str(a.get("name", "")),
                str(a.get("role", "")),
                str(a.get("decision", "")),
                "",
                str(a.get("date", "")),
            ]
        )
    t = make_table(ap, avail_width)
    out.append(t)
    out.append(PageBreak())
    toc = TableOfContents()
    toc.levelStyles = [ST["toc0"], ST["toc1"]]
    out.append(Paragraph("Contents", ST["h1"]))
    out.append(toc)
    out.append(PageBreak())
    return out


class NumberedCanvas(rl_canvas.Canvas):
    """Adds 'Page X of Y' after layout is known."""

    def __init__(self, *a, **k):
        super().__init__(*a, **k)
        self._saved = []

    def showPage(self):
        self._saved.append(dict(self.__dict__))
        self._startPage()

    def save(self):
        total = len(self._saved)
        for state in self._saved:
            self.__dict__.update(state)
            if self._pageNumber > 1:
                self.setFont(BASE, 8)
                self.setFillColor(BRAND["muted"])
                self.drawRightString(
                    PAGE[0] - MARGIN, 0.5 * inch, f"Page {self._pageNumber} of {total}"
                )
            super().showPage()
        super().save()


class PRDDoc(BaseDocTemplate):
    def __init__(self, path, meta):
        super().__init__(
            path,
            pagesize=PAGE,
            leftMargin=MARGIN,
            rightMargin=MARGIN,
            topMargin=MARGIN,
            bottomMargin=MARGIN,
            title=str(meta["title"]),
            author=str(meta.get("owner", "")),
            subject="Product Requirements Document",
        )
        self.meta = meta
        frame = Frame(MARGIN, MARGIN, PAGE[0] - 2 * MARGIN, PAGE[1] - 2 * MARGIN, id="f")
        self.addPageTemplates(
            [
                PageTemplate("cover", [frame], onPage=self._cover),
                PageTemplate("body", [frame], onPage=self._body),
            ]
        )

    def _watermark(self, c):
        status = str(self.meta.get("status", "")).lower()
        if status != "approved":
            c.saveState()
            c.setFont(BOLD, 64)
            c.setFillColor(colors.Color(0.42, 0.38, 0.36, alpha=0.08))
            c.translate(PAGE[0] / 2, PAGE[1] / 2)
            c.rotate(40)
            c.drawCentredString(0, 0, str(self.meta.get("status", "DRAFT")).upper())
            c.restoreState()

    def _logo(self, c, x, y, height, align="left"):
        """Draw the approved logo if configured. Returns True if drawn."""
        if not LOGO_PATH or not os.path.exists(LOGO_PATH):
            return False
        img = ImageReader(LOGO_PATH)
        iw, ih = img.getSize()
        w = height * iw / ih
        if align == "right":
            x -= w
        c.drawImage(img, x, y, width=w, height=height, mask="auto")
        return True

    def _cover(self, c, doc):
        c.saveState()
        bar = 0.9 * inch
        c.setFillColor(BRAND["primary"])
        c.rect(0, PAGE[1] - bar, PAGE[0], bar, stroke=0, fill=1)
        c.setFillColor(BRAND["accent"])
        c.rect(0, PAGE[1] - bar - 0.09 * inch, PAGE[0], 0.09 * inch, stroke=0, fill=1)
        if not self._logo(c, MARGIN, PAGE[1] - bar / 2 - LOGO_HEIGHT / 2, LOGO_HEIGHT):
            c.setFont(BOLD, 15)
            c.setFillColor(colors.white)
            c.drawString(MARGIN, PAGE[1] - bar / 2 - 5, BRAND["name"].upper())
        # Status chip: dark text on gold (8:1 contrast).
        status = str(self.meta["status"]).upper()
        c.setFont(BOLD, 8)
        w = stringWidth(status, BOLD, 8) + 16
        x = PAGE[0] - MARGIN - w
        y = PAGE[1] - bar / 2 - 8
        c.setFillColor(BRAND["accent"])
        c.roundRect(x, y, w, 16, 3, stroke=0, fill=1)
        c.setFillColor(BRAND["text"])
        c.drawCentredString(x + w / 2, y + 5, status)
        c.setStrokeColor(BRAND["accent"])
        c.setLineWidth(2)
        c.line(MARGIN, 0.68 * inch, PAGE[0] - MARGIN, 0.68 * inch)
        c.setFont(BASE, 8)
        c.setFillColor(BRAND["muted"])
        c.drawString(MARGIN, 0.5 * inch, str(self.meta["classification"]))
        c.restoreState()
        self._watermark(c)

    def _body(self, c, doc):
        c.saveState()
        y = PAGE[1] - 0.6 * inch
        c.setFillColor(BRAND["primary"])
        c.rect(0, PAGE[1] - 0.12 * inch, PAGE[0], 0.12 * inch, stroke=0, fill=1)
        c.setStrokeColor(BRAND["accent"])
        c.setLineWidth(1.5)
        c.line(MARGIN, y, PAGE[0] - MARGIN, y)
        if not self._logo(c, MARGIN, y + 4, 0.18 * inch):
            c.setFont(BOLD, 8)
            c.setFillColor(BRAND["primary"])
            c.drawString(MARGIN, y + 6, BRAND["name"])
        c.setFont(BASE, 8)
        c.setFillColor(BRAND["muted"])
        c.drawRightString(
            PAGE[0] - MARGIN,
            y + 6,
            f"{self.meta['title']}  |  {self.meta['doc_id']} v{self.meta['version']}",
        )
        c.setStrokeColor(BRAND["rule"])
        c.setLineWidth(0.5)
        c.line(MARGIN, 0.68 * inch, PAGE[0] - MARGIN, 0.68 * inch)
        c.drawString(MARGIN, 0.5 * inch, str(self.meta["classification"]))
        c.restoreState()
        self._watermark(c)

    def afterFlowable(self, f):
        level = getattr(f, "_toc_level", None)
        if level is not None:
            self.notify("TOCEntry", (level, f.getPlainText(), self.page))


def render_pdf(md_text: str, out_path) -> None:
    meta, body = split_front_matter(md_text)
    doc = PRDDoc(str(out_path), meta)
    avail = PAGE[0] - 2 * MARGIN
    story = cover_and_control(meta, avail) + body_flowables(body, avail)
    doc.multiBuild(story, canvasmaker=NumberedCanvas)
